//! VIBE-owned rules. Native CLI profiles and user-authored rule files stay untouched.
use anyhow::{Context, Result, ensure};
use serde::{Deserialize, Serialize};
use std::{
    fs,
    io::{Read, Write},
    path::{Component, Path, PathBuf},
};

pub const MAX_TEXT: usize = 8 * 1024;
const MAX_CONFIG: u64 = 64 * 1024;
const GENERATED: &str =
    "---\ntrigger: always_on\n---\n<!-- Generated by VIBE scoped rules; do not edit. -->\n";

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct Rules {
    pub version: u32,
    pub inherit_global: bool,
    pub text: String,
    pub file: String,
}
impl Default for Rules {
    fn default() -> Self {
        Self {
            version: 1,
            inherit_global: true,
            text: String::new(),
            file: String::new(),
        }
    }
}

pub fn global_path() -> Result<PathBuf> {
    Ok(crate::storage::workspace_preferences_path()?.with_file_name("rules.json"))
}
pub fn workspace_path(root: &Path) -> Result<PathBuf> {
    scoped_path(root, Path::new(".vibe/rules.json"))
}

fn scoped_path(root: &Path, relative: &Path) -> Result<PathBuf> {
    ensure!(
        !relative.as_os_str().is_empty()
            && relative
                .components()
                .all(|c| matches!(c, Component::Normal(_))),
        "A szabályfájl útvonala workspace-en belüli relatív út legyen."
    );
    let root = root.canonicalize().context("Workspace nem található")?;
    let mut path = root.clone();
    for component in relative.components() {
        path.push(component);
        match fs::symlink_metadata(&path) {
            Ok(_) => {
                let resolved = path.canonicalize()?;
                ensure!(
                    resolved.starts_with(&root),
                    "A szabályfájl kilép a workspace-ből."
                );
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
    }
    Ok(path)
}
fn read(path: &Path, limit: u64) -> Result<String> {
    let mut bytes = Vec::new();
    fs::File::open(path)?
        .take(limit + 1)
        .read_to_end(&mut bytes)?;
    ensure!(bytes.len() as u64 <= limit, "A szabályfájl túl nagy.");
    String::from_utf8(bytes).context("A szabályfájl UTF-8 kódolású legyen")
}
fn valid_text(text: &str) -> Result<()> {
    ensure!(
        text.len() <= MAX_TEXT,
        "Legfeljebb 8 KiB szabályszöveg adható meg mezőnként."
    );
    ensure!(
        !text
            .chars()
            .any(|c| c.is_control() && c != '\n' && c != '\t' && c != '\r'),
        "Vezérlőkarakter nem lehet szabályszövegben."
    );
    Ok(())
}
pub fn load(path: &Path) -> Result<Rules> {
    match read(path, MAX_CONFIG) {
        Ok(text) => {
            let rules: Rules = serde_json::from_str(&text).context("Hibás szabálykonfiguráció")?;
            validate(&rules)?;
            Ok(rules)
        }
        Err(error)
            if error
                .downcast_ref::<std::io::Error>()
                .is_some_and(|e| e.kind() == std::io::ErrorKind::NotFound) =>
        {
            Ok(Rules::default())
        }
        Err(error) => Err(error),
    }
}
fn validate(rules: &Rules) -> Result<()> {
    ensure!(rules.version == 1, "Nem támogatott szabályverzió.");
    valid_text(&rules.text)?;
    ensure!(rules.file.len() <= 512, "Túl hosszú fájlútvonal.");
    Ok(())
}
fn atomic_write(path: &Path, bytes: &[u8]) -> Result<()> {
    let parent = path.parent().context("Hiányzó szabálykönyvtár")?;
    fs::create_dir_all(parent)?;
    let mut file = tempfile::NamedTempFile::new_in(parent)?;
    file.write_all(bytes)?;
    file.as_file().sync_all()?;
    file.persist(path).map_err(|e| e.error)?;
    Ok(())
}
pub fn save(path: &Path, rules: &Rules) -> Result<()> {
    validate(rules)?;
    // Never replace corrupt/newer-version settings with defaults.
    load(path)?;
    atomic_write(path, &serde_json::to_vec_pretty(rules)?)
}
pub fn save_workspace(root: &Path, rules: &Rules) -> Result<()> {
    // Validate the included file before committing the configuration.
    effective_at(root, &Rules::default(), rules)?;
    save(&workspace_path(root)?, rules)
}
pub fn effective(root: &Path) -> Result<String> {
    let workspace = load(&workspace_path(root)?)?;
    let global = if workspace.inherit_global {
        load(&global_path()?)?
    } else {
        Rules::default()
    };
    effective_at(root, &global, &workspace)
}
fn effective_at(root: &Path, global: &Rules, workspace: &Rules) -> Result<String> {
    validate(workspace)?;
    let mut sections = Vec::new();
    if workspace.inherit_global && !global.text.trim().is_empty() {
        valid_text(&global.text)?;
        sections.push(format!(
            "Global VIBE rules (lower priority):\n{}",
            global.text
        ));
    }
    if !workspace.text.trim().is_empty() {
        sections.push(format!(
            "Workspace VIBE rules (override conflicting global VIBE rules):\n{}",
            workspace.text
        ));
    }
    if !workspace.file.trim().is_empty() {
        let text = read(
            &scoped_path(root, Path::new(workspace.file.trim()))?,
            MAX_TEXT as u64,
        )?;
        valid_text(&text)?;
        sections.push(format!(
            "Local workspace rule file (highest VIBE rule priority):\n{text}"
        ));
    }
    let result = sections.join("\n\n");
    ensure!(
        result.len() <= 12 * 1024,
        "Az összevont szabályok legfeljebb 12 KiB méretűek lehetnek."
    );
    Ok(result)
}

pub fn configure_codex(command: &mut portable_pty::CommandBuilder, root: &Path) -> Result<()> {
    let text = effective(root)?;
    if !text.is_empty() {
        command.args([
            "-c",
            &format!("developer_instructions={}", serde_json::to_string(&text)?),
        ]);
    }
    Ok(())
}

/// AGY reads standard workspace rule files. Only this explicitly marked file is owned by VIBE.
pub fn configure_antigravity(root: &Path) -> Result<()> {
    let text = effective(root)?;
    let path = scoped_path(root, Path::new(".agents/rules/vibe-scoped.md"))?;
    if path.exists() {
        ensure!(
            read(&path, MAX_CONFIG)?.starts_with(GENERATED),
            "A .agents/rules/vibe-scoped.md már létezik, nem VIBE-fájl; nem írható felül."
        );
        if text.is_empty() {
            fs::remove_file(path)?;
            return Ok(());
        }
    } else if text.is_empty() {
        return Ok(());
    }
    atomic_write(&path, format!("{GENERATED}\n{text}\n").as_bytes())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn workspace_override_disable_and_isolation() {
        let a = tempfile::tempdir().unwrap();
        let b = tempfile::tempdir().unwrap();
        let global = Rules {
            text: "Globális".into(),
            ..Rules::default()
        };
        let mut local = Rules {
            text: "Helyi".into(),
            ..Rules::default()
        };
        fs::write(a.path().join("rules.md"), "Fájl").unwrap();
        local.file = "rules.md".into();
        save_workspace(a.path(), &local).unwrap();
        let combined = effective_at(
            a.path(),
            &global,
            &load(&workspace_path(a.path()).unwrap()).unwrap(),
        )
        .unwrap();
        assert!(combined.find("Globális").unwrap() < combined.find("Helyi").unwrap());
        assert!(combined.find("Helyi").unwrap() < combined.find("Fájl").unwrap());
        local.inherit_global = false;
        assert!(
            !effective_at(a.path(), &global, &local)
                .unwrap()
                .contains("Globális")
        );
        assert_eq!(
            load(&workspace_path(b.path()).unwrap()).unwrap(),
            Rules::default()
        );
        assert!(!b.path().join(".vibe").exists());
    }
    #[test]
    fn invalid_config_and_paths_are_preserved() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("broken.json");
        fs::write(&path, "broken").unwrap();
        assert!(save(&path, &Rules::default()).is_err());
        assert_eq!(fs::read_to_string(path).unwrap(), "broken");
        for name in ["../secret.md", "/secret.md", "C:\\secret.md"] {
            let rules = Rules {
                file: name.into(),
                ..Rules::default()
            };
            assert!(save_workspace(root.path(), &rules).is_err());
        }
        let rules = Rules {
            text: "x".repeat(MAX_TEXT + 1),
            ..Rules::default()
        };
        assert!(save_workspace(root.path(), &rules).is_err());
        assert!(!root.path().join(".vibe").exists());
    }
    #[test]
    fn native_command_rules_are_arguments_not_shell_code() {
        let root = tempfile::tempdir().unwrap();
        save_workspace(
            root.path(),
            &Rules {
                inherit_global: false,
                text: "Írj magyarul.\n\"$()\"".into(),
                ..Rules::default()
            },
        )
        .unwrap();
        let mut command = portable_pty::CommandBuilder::new("not-executed");
        configure_codex(&mut command, root.path()).unwrap();
        let args = command.get_argv();
        assert_eq!(args[1], "-c");
        assert!(
            args[2]
                .to_string_lossy()
                .starts_with("developer_instructions=\"")
        );
        configure_antigravity(root.path()).unwrap();
        let generated = root.path().join(".agents/rules/vibe-scoped.md");
        assert!(
            fs::read_to_string(&generated)
                .unwrap()
                .contains("Írj magyarul.")
        );
        fs::write(&generated, "user-owned").unwrap();
        assert!(configure_antigravity(root.path()).is_err());
        assert_eq!(fs::read_to_string(generated).unwrap(), "user-owned");
    }
}
